(6393946, 946467, 93565, '<td valign="top">Bizarre, but cool. A dog like that just reminds me of royalty or something, of cleanliness, not squalor, at any rate. One of my faves from this challenge. Hope his paws were alright!<br/>Also, great location.</td>', 'Bizarre, but cool. A dog like that just reminds me of royalty or something, of cleanliness, not squalor, at any rate. One of my faves from this challenge. Hope his paws were alright!Also, great location.', '2011-04-24 09:31:45.000000', NULL, 1),
(6393948, 947094, 93565, '<td valign="top">Hey, an object that actually belongs in an empty room! Amazing!<br/>Cheekiness aside, this was one of my faves from the challenge. No suggestions, really. Nice submission.</td>', 'Hey, an object that actually belongs in an empty room! Amazing!Cheekiness aside, this was one of my faves from the challenge. No suggestions, really. Nice submission.', '2011-04-24 09:33:03.000000', NULL, 1),
(6393950, 947150, 93565, '<td valign="top">Best done of the "left behind"/nostalgia/sorrow that was type shots, but the cliche is still there and this hasn''t completely elevated itself beyond that.</td>', 'Best done of the "left behind"/nostalgia/sorrow that was type shots, but the cliche is still there and this hasn''t completely elevated itself beyond that.', '2011-04-24 09:34:38.000000', NULL, 1),
(6394032, 946914, 61084, '<td valign="top">Love the room, but did you read the whole challenge description? Where is the single object that is supposed to be in the room? Not voting yet....later in the week. Nice color and textures though, and the fish-eye works really well here.</td>', 'Love the room, but did you read the whole challenge description? Where is the single object that is supposed to be in the room? Not voting yet....later in the week. Nice color and textures though, and the fish-eye works really well here.', '2011-04-24 13:23:13.000000', NULL, 1),
(6394033, 947151, 61084, '<td valign="top">Awesome shot, but which one of the many things decorating your room is the single object? Not voting until later this week.</td>', 'Awesome shot, but which one of the many things decorating your room is the single object? Not voting until later this week.', '2011-04-24 13:23:36.000000', NULL, 1),
(6394034, 947159, 61084, '<td valign="top">Was this meant for the Sadness challenge? I really like the shot, but I don''t see how it relates to an Empty Room challenge when you can''t see...the room. Not voting until later this week. Again, I like the photo on it''s own merits.</td>', 'Was this meant for the Sadness challenge? I really like the shot, but I don''t see how it relates to an Empty Room challenge when you can''t see...the room. Not voting until later this week. Again, I like the photo on it''s own merits.', '2011-04-24 13:26:51.000000', NULL, 1),
